SELECT COUNT(*)
FROM eafs_ordered_node
WHERE bucket = #{bucket}

SELECT *
FROM eafs_ordered_node
WHERE bucket = #{bucket}
  AND record_id = #{recordId}
LIMIT 1

SELECT *
FROM eafs_ordered_node
WHERE bucket = #{bucket}
  AND rindex <= #{rindex}
ORDER BY rindex DESC, chain_order DESC
LIMIT 1

SELECT *
FROM eafs_ordered_node
WHERE bucket = #{bucket}
  AND chain_order >= #{fromOrder}
ORDER BY chain_order ASC

mapper.update:
UPDATE eafs_ordered_node
SET chain_order = -chain_order
WHERE bucket = #{bucket}
  AND chain_order >= #{fromOrder}

UPDATE eafs_ordered_node
SET chain_order = -chain_order + 1
WHERE bucket = #{bucket}
  AND chain_order <= -#{fromOrder}

