INSERT INTO eafs_ordered_node (
    bucket, chain_order, record_id, rindex, prev_node_id, next_node_id, chain_key_hex, payload_base64
) VALUES (
    #{bucket}, #{chainOrder}, #{recordId}, #{rindex}, #{prevNodeId}, #{nextNodeId}, #{chainKeyHex}, #{payloadBase64}
)

mapper.update:
UPDATE eafs_ordered_node
SET prev_node_id = #{prevNodeId},
    next_node_id = #{nextNodeId}
WHERE id = #{id}
